edges=[]
for typ,block in data.items():
 for line in block.splitlines():
  if not line:continue
  a,b,r=line.split('|')
  if r=='SKIP':continue
  assert a in words and b in words,(a,b)
  edges.append(dict(a=a,b=b,type=typ,reason=r))
assert len({(e['a'],e['b'],e['type']) for e in edges})==len(edges)
pairs=defaultdict(list)
for e in edges:pairs[tuple(sorted((e['a'],e['b'])))].append(e)
counts={t:sum(any(e['type']==t for e in es) for es in pairs.values()) for t in data}
deg=Counter();fd=Counter();fav={'Характеристика','Противопоставление','Разновидность'}
for a,b in pairs:deg.update([a,b])
fps={p for p,es in pairs.items() if any(e['type'] in fav for e in es)}
for a,b in fps:fd.update([a,b])
multi=sum(len({e['type'] for e in es})>1 for es in pairs.values())
report=['# E04: сопоставление независимого списка из 100 слов','','Источник: `independent-candidates-100-e04.md`. Дата: 28 сентября 2026 года.','','## Метод и границы результата','','Сопоставляются только слова E04 в зафиксированных значениях. Предыдущие таблицы связей и их числа при разметке не использованы. Названия типов сохранены для читаемости сравнения; два дополнительных отношения выделены из текущего материала. Это не слепой эксперимент и не проверка с игроками.','','Первая экспертная разметка, не исчерпывающий аудит всех 4 950 пар. Условия в объяснениях обязательны. Пары без объяснения не считаются невозможными. Указаны как прямые отношения, так и условные цепочки через промежуточный процесс: последние нельзя автоматически приравнивать к простым игровым связям.','','Единица подсчёта — неупорядоченная пара. Направление и каждое объяснение сохраняются отдельно. Два направления одного типа дают одну пару этого типа. Пересечение типов — пара, имеющая оба типа; число объяснений поэтому больше числа пар.','','Характеристика: носитель → признак. Разновидность: частное → общее, с явными оговорками. Состав: составляющее → процесс/целое. Причина: возможное возникновение результата. Помощь и помеха описывают условия выполнения. Предшествование не доказывает причинности. Регулирование описывает допуск или предписание действия. «Стороны одной операции» связывает разные роли в одной ситуации и не считается противоположностью.','','## Итог','',f'Найдено **{len(pairs)} уникальных пар**, **{len(edges)} объяснений**. Ненулевых типов: **{sum(n>0 for n in counts.values())}**. Пар с несколькими типами: **{multi}**. Слов с найденными соседями: **{len(deg)} из 100**.', '',f'Три приоритетных типа: **{len(fps)} уникальных пар**, **{len(fd)} слов**. Сумма не означает полную оценку потенциальной связности.', '', '| Тип | Уникальных пар | Объяснений |','|---|---:|---:|']
for t,n in sorted(counts.items(),key=lambda x:-x[1]):report.append(f'| {t} | {n} | {sum(e["type"]==t for e in edges)} |')
report+=['','## Пересечения типов','','| Тип 1 | Тип 2 | Общих пар |','|---|---|---:|']
for t,u in combinations(data,2):
 n=sum({t,u}.issubset({e['type'] for e in es}) for es in pairs.values())
 if n:report.append(f'| {t} | {u} | {n} |')
report+=['','## Пары с несколькими типами','','| Пара | Типы |','|---|---|']
for (a,b),es in sorted(pairs.items()):
 ts={e['type'] for e in es}
 if len(ts)>1:report.append(f'| {a} ↔ {b} | '+ '; '.join(sorted(ts))+' |')
report+=['','## Реестр объяснений','','Все строки — аналитические кандидаты. Внешняя проверка ниже относится только к указанным естественно-научным примерам, а не всему реестру.','','| № | A | Тип | B | Объяснение и условия |','|---:|---|---|---|---|']
for i,e in enumerate(edges,1):report.append(f"| {i} | {e['a']} | {e['type']} | {e['b']} | {e['reason']} |")
report+=['','## Все слова по числу найденных соседей','','| Слово | Все типы | Три приоритетных типа |','|---|---:|---:|']
for w in sorted(words,key=lambda w:(-deg[w],w)):report.append(f'| {w} | {deg[w]} | {fd[w]} |')
report+=['','## Не размеченные в этом проходе слова','',', '.join(w for w in words if not deg[w])+'.','','Это пробелы разметки, а не доказанная изоляция. Особенно нельзя соединять жанры только общей тематикой или потому, что любой жанр может рассказывать о любом явлении.','','## Не принятые автоматически сочетания','','| Пара | Причина |','|---|---|','| Кипение — испарение | Оба — парообразование, но испарение обычно означает поверхностный процесс, а кипение — объёмный; определение «Испарения» в исходнике слишком широкое. Классификация зависит от уточнения, поэтому пара не посчитана. |','| Снегопад — дождь | Разные осадки, не строгие противоположности. |','| Покупка — продажа | Встречные роли в одной сделке; выделены отдельным типом. |','| Цена — покупка | Цена непосредственно характеризует товар/услугу, а не действие покупки; в характеристику не включена. Мотивационные связи сохранены отдельно. |','| Сказка — миф | Пересечение сюжетов не делает один жанр разновидностью другого. |','| Басня — стихотворение | Басня бывает прозаической; без ограничения универсальная разновидность не установлена. |','| Алгоритм — правило | Последовательность выполнения задачи и правило допустимости действий не тождественны в выбранных значениях. |','| Сбережение — сбережения | В E04 первое — бережное использование природы, второе — накопленные деньги; не синонимы и не разновидности. |','| Сохранение — удаление | Запись данных и устранение их из хранилища контрастны по цели, но не точные обратные операции. В строгий список противопоставлений не включены. |','','## Источники выборочной проверки','','- [USGS: круговорот воды](https://www.usgs.gov/water-science-school/water-cycle): испарение, конденсация, осадки и сток как процессы круговорота.','- [USGS: схема для детей](https://water.usgs.gov/edu/watercycle-kids-beg.html): противоположность испарения и конденсации.','- [NWS: природа грома](https://www.weather.gov/safety/lightning-science-thunder): гром как звук, возникающий из-за молнии.','','Эти источники проверяют фактическое содержание отдельных отношений, но не понятность формулировок детям и не пригодность типа связи для игры.','','## Практический вывод','','В текущем пуле преобладают процессы. Они естественно дают причинные связи, условия выполнения, состав и последовательность; наличие многих процессов не обеспечивает много характеристик или родовидовых пар. Внутри тематической группы может отсутствовать общее родовое слово: категории таблицы не являются игровыми картами. Например, слова «Осадки», «Жанр» и «Парообразование» отсутствуют и не участвовали в подсчёте.','','До отбора карт следует решить, допускаются ли длинные причинные цепочки и условные значения. Не сравнивать сырые итоги с прошлыми пулами как результаты одинакового полного теста: все три прохода остаются неполными.','']
(root/'independent-candidates-100-e04-interactions.md').write_text('\n'.join(report))
(root/'independent-candidates-100-e04-interactions.json').write_text(json.dumps(dict(status='candidate_annotations_not_exhaustive',words=words,relations=edges),ensure_ascii=False,indent=2)+'\n')
